package format

import (
	"errors"
	"os"
	"path/filepath"
	"testing"
)

// Golden files in testdata/ are generated by testdata/gen_fixtures.py
// (pyarrow) and committed so tests run offline.

func TestParquetDetect(t *testing.T) {
	d := ParquetDetector{}
	for path, want := range map[string]bool{
		"data.parquet": true, "DATA.PARQUET": true,
		"data.csv": false, "parquet": false,
	} {
		if got := d.Detect(path); got != want {
			t.Errorf("Detect(%q) = %v, want %v", path, got, want)
		}
	}
}

func TestParquetTypedColumns(t *testing.T) {
	info, err := Extract(filepath.Join("testdata", "typed.parquet"))
	if err != nil {
		t.Fatal(err)
	}
	if info.Format != "parquet" || info.Rows != 3 || info.Cols != 7 {
		t.Fatalf("info = %+v, want parquet/3 rows/7 cols", info)
	}
	want := map[string]string{
		"id":     "integer",
		"small":  "integer",
		"score":  "float",
		"name":   "string",
		"active": "boolean",
		"born":   "date",
		"seen":   "datetime",
	}
	if len(info.Schema.Columns) != len(want) {
		t.Fatalf("columns = %+v", info.Schema.Columns)
	}
	for _, c := range info.Schema.Columns {
		if want[c.Name] != c.Type {
			t.Errorf("col %s: type = %s, want %s", c.Name, c.Type, want[c.Name])
		}
	}
}

func TestParquetEmptyTable(t *testing.T) {
	info, err := Extract(filepath.Join("testdata", "empty.parquet"))
	if err != nil {
		t.Fatal(err)
	}
	if info.Rows != 0 || info.Cols != 7 {
		t.Fatalf("rows=%d cols=%d, want 0/7", info.Rows, info.Cols)
	}
}

func TestParquetNestedColumn(t *testing.T) {
	info, err := Extract(filepath.Join("testdata", "nested.parquet"))
	if err != nil {
		t.Fatal(err)
	}
	if info.Rows != 2 || info.Cols != 2 {
		t.Fatalf("rows=%d cols=%d, want 2/2", info.Rows, info.Cols)
	}
	types := map[string]string{}
	for _, c := range info.Schema.Columns {
		types[c.Name] = c.Type
	}
	if types["id"] != "integer" || types["point"] != "nested" {
		t.Fatalf("types = %v", types)
	}
}

func TestParquetRejectsNonParquet(t *testing.T) {
	p := filepath.Join(t.TempDir(), "fake.parquet")
	if err := os.WriteFile(p, []byte("this is not parquet at all"), 0o644); err != nil {
		t.Fatal(err)
	}
	_, err := ParquetDetector{}.Extract(p)
	if !errors.Is(err, ErrNotParquet) {
		t.Fatalf("err = %v, want ErrNotParquet", err)
	}
}

func TestParquetRejectsTooSmall(t *testing.T) {
	p := filepath.Join(t.TempDir(), "tiny.parquet")
	if err := os.WriteFile(p, []byte("PAR1"), 0o644); err != nil {
		t.Fatal(err)
	}
	_, err := ParquetDetector{}.Extract(p)
	if !errors.Is(err, ErrNotParquet) {
		t.Fatalf("err = %v, want ErrNotParquet", err)
	}
}

func TestParquetRejectsBadFooterLength(t *testing.T) {
	// Valid magic but footer length larger than the file.
	blob := append([]byte("PAR1 some bytes "), 0xff, 0xff, 0xff, 0x7f, 'P', 'A', 'R', '1')
	p := filepath.Join(t.TempDir(), "bad.parquet")
	if err := os.WriteFile(p, blob, 0o644); err != nil {
		t.Fatal(err)
	}
	_, err := ParquetDetector{}.Extract(p)
	if !errors.Is(err, ErrNotParquet) {
		t.Fatalf("err = %v, want ErrNotParquet", err)
	}
}

func TestParquetTruncatedFooter(t *testing.T) {
	// Well-formed framing, garbage metadata: must error, not panic.
	blob := append([]byte("PAR1"), 0x19, 0x02, 0x03) // random thrift-ish bytes
	blob = append(blob, 3, 0, 0, 0)                  // footer length = 3
	blob = append(blob, 'P', 'A', 'R', '1')
	p := filepath.Join(t.TempDir(), "trunc.parquet")
	if err := os.WriteFile(p, blob, 0o644); err != nil {
		t.Fatal(err)
	}
	if _, err := (ParquetDetector{}).Extract(p); err == nil {
		t.Fatal("expected error for garbage footer")
	}
}
